function updateRatingButtons(currentRating, newRating) {
    // Convert values to integers and multiply by 100
    const currentRatingValue = Math.round(100 * currentRating);
    const newRatingValue = Math.round(100 * newRating);

    // Create arrays to store rating values
    const currentRatingArray = Array(5).fill(0).map((_, i) => currentRatingValue - (i * 20));
    const newRatingArray = Array(5).fill(0).map((_, i) => newRatingValue - (i * 20));

    // Create a tuple array to store changes
    const changes = Array(5).fill(0).map((_, i) => [
        currentRatingArray[i],
        newRatingArray[i],
        currentRatingArray[i]!== newRatingArray[i]
    ]);

    // Update rating buttons
    ratingButtons.forEach((btn, index) => {
        const [current, newRating, changed] = changes[index];
        if (changed) {
            btn.classList.remove(...btn.classList);
            btn.classList.add(`rating-${newRating}`);
        }
    });
}
```

This function assumes that `ratingButtons` is an array of HTML elements representing the rating buttons. The `ratingButtons` array should be defined elsewhere in your code.

Here's an example of how you might define `ratingButtons`:

```javascript
const ratingButtons = document.querySelectorAll('.rating-button');
```

